using Microsoft.Win32;
using System.Runtime.InteropServices;
using System.Text.RegularExpressions;
namespace Arcoll.WinUI3.Services.PenteFino;
/// <summary>Fontes complementares somente leitura; nenhum serviço/tarefa/COM é alterado.</summary>
public static class AdditionalDiagnostics
{
    public static void Startup(List<Finding> items,List<string> notes,CancellationToken ct){
        using(var root=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,RegistryView.Registry64))using(var services=root.OpenSubKey(@"SYSTEM\CurrentControlSet\Services")){
            if(services is not null)foreach(var name in services.GetSubKeyNames().Take(2000)){ct.ThrowIfCancellationRequested();using var service=services.OpenSubKey(name);if(service?.GetValue("Start")is not int start||start!=2)continue;var type=service.GetValue("Type")is int n?n:0;if((type&0x30)==0)continue;items.Add(new(ResultsStore.Hash("service|"+name),"startup",service.GetValue("DisplayName")as string??name,@"HKLM\SYSTEM\CurrentControlSet\Services\"+name,0,"Serviço com inicialização automática. Dependências e impacto não foram aferidos.","Somente revisão; não desabilitar serviços automaticamente",false,"info",Severity:"review"));}
        }
        object? serviceObject=null;
        try{var type=Type.GetTypeFromProgID("Schedule.Service");if(type is null){notes.Add("Agendador de Tarefas indisponível.");return;}serviceObject=Activator.CreateInstance(type);dynamic scheduler=serviceObject!;scheduler.Connect();var stack=new Stack<object>();stack.Push(scheduler.GetFolder("\\"));var count=0;
            while(stack.Count>0&&count<2000){ct.ThrowIfCancellationRequested();dynamic folder=stack.Pop();try{dynamic tasks=folder.GetTasks(1);try{for(var i=1;i<=(int)tasks.Count&&count<2000;i++){ct.ThrowIfCancellationRequested();dynamic task=tasks.Item(i);try{count++;if(!(bool)task.Enabled)continue;dynamic definition=task.Definition;try{dynamic triggers=definition.Triggers;try{var boot=false;for(var j=1;j<=(int)triggers.Count;j++){dynamic trigger=triggers.Item(j);try{var kind=(int)trigger.Type;if(kind is 8 or 9)boot=true;}finally{Release(trigger);}}if(boot){string path=task.Path;items.Add(new(ResultsStore.Hash("task|"+path),"startup",(string)task.Name,"Agendador: "+path,0,"Tarefa habilitada com gatilho de boot/logon. Pode executar manutenção ou proteção.","Somente revisão; nenhuma tarefa é alterada",false,"info",Severity:"review"));}}finally{Release(triggers);}}finally{Release(definition);}}finally{Release(task);}}}finally{Release(tasks);}dynamic children=folder.GetFolders(0);try{for(var i=1;i<=(int)children.Count;i++)stack.Push(children.Item(i));}finally{Release(children);}}finally{Release(folder);}}
            while(stack.Count>0)Release(stack.Pop());if(count>=2000)notes.Add("Tarefas limitadas a 2.000 registros; inventário parcial.");
        }catch(Exception error)when(error is COMException or UnauthorizedAccessException or Microsoft.CSharp.RuntimeBinder.RuntimeBinderException){notes.Add("Tarefas não completamente verificadas: "+error.Message);}finally{Release(serviceObject);}
        notes.Add("Serviços e tarefas são inventariados somente para revisão. Impacto real por programa no boot/ETW não foi medido; não é inferido a partir das quantidades.");
    }
    private static void Release(object? value){if(value is not null&&Marshal.IsComObject(value))Marshal.FinalReleaseComObject(value);}
    public static void Registry(RegistryKey root,RegistryHive hive,RegistryView view,List<Finding> items,CancellationToken ct){
        const string clsid=@"Software\Classes\CLSID";using(var classes=root.OpenSubKey(clsid)){if(classes is not null)foreach(var id in classes.GetSubKeyNames().Take(6000)){ct.ThrowIfCancellationRequested();using var server=classes.OpenSubKey(id+@"\InprocServer32");var file=server?.GetValue("")as string;if(file is null||!RegistryValues.MissingLocalPath(file))continue;var path=RegistryValues.Ref(hive,view,clsid+"\\"+id+@"\InprocServer32","");items.Add(new(ResultsStore.Hash(path),"registry",id,path,0,"Servidor COM aponta para DLL local não encontrada. Pode depender de instalação sob demanda.","Somente revisão; CLSID/COM não é removido automaticamente",false,"info",Severity:"review"));}}
        const string uninstall=@"Software\Microsoft\Windows\CurrentVersion\Uninstall";using(var programs=root.OpenSubKey(uninstall)){if(programs is not null)foreach(var id in programs.GetSubKeyNames().Take(2500)){ct.ThrowIfCancellationRequested();using var program=programs.OpenSubKey(id);var command=program?.GetValue("UninstallString")as string??"";var match=Regex.Match(command,"^\\\"([^\\\"]+\\.exe)\\\"|^([A-Za-z]:\\\\.+?\\.exe)(?:\\s|$)",RegexOptions.IgnoreCase);var path=match.Groups[1].Success?match.Groups[1].Value:match.Groups[2].Value;if(path.Length==0||!RegistryValues.MissingLocalPath(path))continue;var reference=RegistryValues.Ref(hive,view,uninstall+"\\"+id,"UninstallString");items.Add(new(ResultsStore.Hash(reference),"registry",program?.GetValue("DisplayName")as string??id,reference,0,"Desinstalador local não encontrado. A entrada pode corresponder a aplicativo com reparação sob demanda.","Somente revisão; não remover a entrada de desinstalação",false,"info",Severity:"review"));}}
        const string mui=@"Software\Classes\Local Settings\Software\Microsoft\Windows\Shell\MuiCache";using(var cache=root.OpenSubKey(mui)){if(cache is not null)foreach(var name in cache.GetValueNames().Take(4000)){ct.ThrowIfCancellationRequested();var suffixes=new[]{".FriendlyAppName",".ApplicationCompany"};var suffix=suffixes.FirstOrDefault(x=>name.EndsWith(x,StringComparison.OrdinalIgnoreCase));if(suffix is null)continue;var path=name[..^suffix.Length];if(!RegistryValues.MissingLocalPath(path))continue;var reference=RegistryValues.Ref(hive,view,mui,name);items.Add(new(ResultsStore.Hash(reference),"registry",Path.GetFileName(path),reference,0,"Cache de descrição de executável local não encontrado.","Somente diagnóstico de MUI Cache",false,"info"));}}
    }
}
